import { useState, useEffect } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import axios from 'axios';

export default function TakeQuiz() {
  const { id } = useParams();
  const navigate = useNavigate();
  const [quiz, setQuiz] = useState(null);
  const [responses, setResponses] = useState({});
  const [timeLeft, setTimeLeft] = useState(0);
  const [submitted, setSubmitted] = useState(false);

  useEffect(() => {
    axios.get(`http://localhost:5000/api/quizzes/${id}/start`)
      .then(res => {
        setQuiz(res.data);
        setTimeLeft(res.data.timeLimit);
      });
  }, [id]);

  useEffect(() => {
    if (timeLeft <= 0 && quiz && !submitted) handleSubmit();
    const timer = setInterval(() => {
      setTimeLeft(prev => prev > 0 ? prev - 1 : 0);
    }, 1000);
    return () => clearInterval(timer);
  }, [timeLeft, quiz, submitted]);

  const handleAnswer = (questionId, optionId) => {
    setResponses(prev => ({ ...prev, [questionId]: optionId }));
  };

  const handleSubmit = async () => {
    if (submitted) return;
    setSubmitted(true);
    const formattedResponses = Object.keys(responses).map(qId => ({
      questionId: qId,
      selectedOptionId: responses[qId]
    }));

    try {
      await axios.post(`http://localhost:5000/api/quizzes/${id}/submit`, {
        responses: formattedResponses,
        totalTimeTaken: quiz.timeLimit - timeLeft
      });
      navigate('/leaderboard');
    } catch (err) {
      alert('Submission failed');
    }
  };

  if (!quiz) return <div className="p-6">Loading...</div>;

  return (
    <div className="p-6 max-w-3xl mx-auto">
      <div className="text-right text-xl font-bold text-red-600 mb-4">
        ⏱️ {Math.floor(timeLeft / 60)}:{(timeLeft % 60).toString().padStart(2, '0')}
      </div>

      <h1 className="text-2xl mb-6">{quiz.title}</h1>

      {quiz.questions.map(q => (
        <div key={q._id} className="mb-6 p-4 border rounded">
          <h3 className="text-lg mb-2">{q.text}</h3>
          {q.options.map(opt => (
            <label key={opt._id} className="block mt-2">
              <input
                type="radio"
                name={q._id}
                value={opt._id}
                onChange={() => handleAnswer(q._id, opt._id)}
                className="mr-2"
              />
              {opt.text}
            </label>
          ))}
        </div>
      ))}

      <button
        onClick={handleSubmit}
        disabled={submitted}
        className="bg-blue-600 text-white px-6 py-2 rounded disabled:opacity-50"
      >
        {submitted ? 'Submitted!' : 'Submit Quiz'}
      </button>
    </div>
  );
}
